package com.fathom.account;
import com.fathom.common.BaseEntity;import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="financial_accounts")
public class FinancialAccount extends BaseEntity { @Id private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(nullable=false) private String name; @Column(name="institution_name") private String institutionName; @Enumerated(EnumType.STRING) @Column(name="account_type",nullable=false) private AccountType accountType; @Column(length=3,nullable=false) private String currency="INR"; @Column(name="masked_identifier") private String maskedIdentifier; @Column(nullable=false) private boolean active=true; @PrePersist void initId(){if(id==null)id=UUID.randomUUID();}
public UUID getId(){return id;} public UUID getUserId(){return userId;} public String getName(){return name;} public String getInstitutionName(){return institutionName;} public AccountType getAccountType(){return accountType;} public String getCurrency(){return currency;} public String getMaskedIdentifier(){return maskedIdentifier;} public boolean isActive(){return active;} public void setUserId(UUID v){userId=v;} public void setName(String v){name=v;} public void setInstitutionName(String v){institutionName=v;} public void setAccountType(AccountType v){accountType=v;} public void setCurrency(String v){currency=v;} public void setMaskedIdentifier(String v){maskedIdentifier=v;} public void setActive(boolean v){active=v;} }
